import{_ as e,o as a,c as i,a2 as r}from"./chunks/framework.CD2m2Tvf.js";const y=JSON.parse('{"title":"Security Audit & OWASP Top 10 Mapping","description":"","frontmatter":{},"headers":[],"relativePath":"06-security.md","filePath":"06-security.md"}'),n={name:"06-security.md"};function l(d,t,o,s,c,g){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="security-audit-owasp-top-10-mapping" tabindex="-1">Security Audit &amp; OWASP Top 10 Mapping <a class="header-anchor" href="#security-audit-owasp-top-10-mapping" aria-label="Permalink to &quot;Security Audit &amp; OWASP Top 10 Mapping&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">OWASP Vulnerability</th><th style="text-align:left;">Risk in Tracing Platform</th><th style="text-align:left;">Implemented Defense</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>A01: Broken Access Control</strong></td><td style="text-align:left;">Unauthorized access to tenant traces</td><td style="text-align:left;">Tenant ID validation middleware (<code>security/tenant.py</code>) and RBAC scope enforcement.</td></tr><tr><td style="text-align:left;"><strong>A02: Cryptographic Failures</strong></td><td style="text-align:left;">Eavesdropping on trace telemetry</td><td style="text-align:left;">Mandatory TLS 1.3 in transit; mTLS for inter-service collector communication.</td></tr><tr><td style="text-align:left;"><strong>A03: Injection</strong></td><td style="text-align:left;">SQL/NoSQL injection via span tags</td><td style="text-align:left;">Parameterized SQLAlchemy queries; strict Pydantic payload validation.</td></tr><tr><td style="text-align:left;"><strong>A04: Insecure Design</strong></td><td style="text-align:left;">Unbounded memory consumption by large traces</td><td style="text-align:left;">Maximum span payload limiter (<code>security/payload_limiter.py</code>) capped at 1MB.</td></tr><tr><td style="text-align:left;"><strong>A05: Security Misconfiguration</strong></td><td style="text-align:left;">Leaked database credentials or keys</td><td style="text-align:left;">All secrets injected via environment variables; none committed to source control.</td></tr><tr><td style="text-align:left;"><strong>A06: Vulnerable Components</strong></td><td style="text-align:left;">Outdated third-party packages</td><td style="text-align:left;">Regular <code>pip-audit</code> checks in CI/CD pipeline.</td></tr><tr><td style="text-align:left;"><strong>A07: Identification / Auth Failures</strong></td><td style="text-align:left;">Spoofed trace ingestion</td><td style="text-align:left;">Cryptographic API key validation with rate limiting (<code>security/api_key.py</code>).</td></tr><tr><td style="text-align:left;"><strong>A08: Software / Data Integrity</strong></td><td style="text-align:left;">Tampered span timestamps or trace IDs</td><td style="text-align:left;">Strict W3C traceparent 128-bit hex format validation.</td></tr><tr><td style="text-align:left;"><strong>A09: Logging &amp; Monitoring Failures</strong></td><td style="text-align:left;">Undetected collector outages</td><td style="text-align:left;">Self-monitoring Prometheus metrics (<code>/metrics</code>) tracking ingestion rate and drop rate.</td></tr><tr><td style="text-align:left;"><strong>A10: Server-Side Request Forgery</strong></td><td style="text-align:left;">Malicious webhook triggers in alert routing</td><td style="text-align:left;">Outbound webhook URLs restricted to approved private subnets.</td></tr></tbody></table><hr><h3 id="pii-redaction-engine" tabindex="-1">PII Redaction Engine <a class="header-anchor" href="#pii-redaction-engine" aria-label="Permalink to &quot;PII Redaction Engine&quot;">​</a></h3><p>Located in <code>backend/src/security/pii_filter.py</code>:</p><ul><li>Redacts credit card numbers (Luhn algorithm match).</li><li>Redacts Social Security Numbers (SSN regex).</li><li>Redacts JWT tokens and authorization bearer strings in span attributes before persistence.</li></ul>',6)])])}const u=e(n,[["render",l]]);export{y as __pageData,u as default};
